-- Convert only the known local dashboard demo records to the structured domain ERD v1 contract.
-- User-created legacy Architecture rows are preserved and remain available to the UI fallback.
UPDATE "Architecture"
SET "content" = '{"kind":"domain-erd","schemaVersion":1,"name":"Yusung Harness Domain Model","sourceRevision":"demo-architecture-v1","entities":[{"id":"project","name":"Project","domain":"project","description":"Repository-scoped harness workspace.","fields":[{"name":"id","type":"Int","nullable":false,"primaryKey":true},{"name":"repoPath","type":"String","nullable":false,"unique":true},{"name":"repoType","type":"RepoType","nullable":false}]},{"id":"plan","name":"Plan","domain":"planning","fields":[{"name":"id","type":"Int","nullable":false,"primaryKey":true},{"name":"projectId","type":"Int","nullable":false,"foreignKey":true},{"name":"version","type":"Int","nullable":false}]},{"id":"task","name":"Task","domain":"delivery","fields":[{"name":"id","type":"Int","nullable":false,"primaryKey":true},{"name":"projectId","type":"Int","nullable":false,"foreignKey":true},{"name":"planId","type":"Int","nullable":false,"foreignKey":true},{"name":"status","type":"TaskStatus","nullable":false,"default":"PENDING"}]},{"id":"draft","name":"Draft","domain":"planning","fields":[{"name":"id","type":"Int","nullable":false,"primaryKey":true},{"name":"projectId","type":"Int","nullable":false,"foreignKey":true}]},{"id":"architecture","name":"Architecture","domain":"architecture","fields":[{"name":"id","type":"Int","nullable":false,"primaryKey":true},{"name":"projectId","type":"Int","nullable":false,"foreignKey":true},{"name":"content","type":"DomainErdJson","nullable":false}]},{"id":"asset","name":"Asset","domain":"design","fields":[{"name":"id","type":"Int","nullable":false,"primaryKey":true},{"name":"projectId","type":"Int","nullable":false,"foreignKey":true},{"name":"planId","type":"Int","nullable":false,"foreignKey":true},{"name":"taskId","type":"Int","nullable":false,"foreignKey":true}]},{"id":"wireframe","name":"Wireframe","domain":"design","fields":[{"name":"id","type":"Int","nullable":false,"primaryKey":true},{"name":"projectId","type":"Int","nullable":false,"foreignKey":true},{"name":"planId","type":"Int","nullable":false,"foreignKey":true},{"name":"taskId","type":"Int","nullable":false,"foreignKey":true}]},{"id":"design","name":"Design","domain":"design","fields":[{"name":"id","type":"Int","nullable":false,"primaryKey":true},{"name":"projectId","type":"Int","nullable":false,"foreignKey":true},{"name":"planId","type":"Int","nullable":false,"foreignKey":true},{"name":"taskId","type":"Int","nullable":false,"foreignKey":true},{"name":"wireframeId","type":"Int","nullable":false,"foreignKey":true},{"name":"assetId","type":"Int","nullable":false,"foreignKey":true}]},{"id":"review","name":"Review","domain":"quality","fields":[{"name":"id","type":"Int","nullable":false,"primaryKey":true},{"name":"projectId","type":"Int","nullable":false,"foreignKey":true},{"name":"planId","type":"Int","nullable":false,"foreignKey":true}]}],"relationships":[{"id":"project-plans","label":"plans","source":{"entityId":"project","field":"id","cardinality":"1"},"target":{"entityId":"plan","field":"projectId","cardinality":"N"}},{"id":"project-tasks","label":"tasks","source":{"entityId":"project","field":"id","cardinality":"1"},"target":{"entityId":"task","field":"projectId","cardinality":"N"}},{"id":"project-drafts","label":"drafts","source":{"entityId":"project","field":"id","cardinality":"1"},"target":{"entityId":"draft","field":"projectId","cardinality":"N"}},{"id":"project-architectures","label":"architectures","source":{"entityId":"project","field":"id","cardinality":"1"},"target":{"entityId":"architecture","field":"projectId","cardinality":"N"}},{"id":"project-assets","label":"assets","source":{"entityId":"project","field":"id","cardinality":"1"},"target":{"entityId":"asset","field":"projectId","cardinality":"N"}},{"id":"project-wireframes","label":"wireframes","source":{"entityId":"project","field":"id","cardinality":"1"},"target":{"entityId":"wireframe","field":"projectId","cardinality":"N"}},{"id":"project-designs","label":"designs","source":{"entityId":"project","field":"id","cardinality":"1"},"target":{"entityId":"design","field":"projectId","cardinality":"N"}},{"id":"project-reviews","label":"reviews","source":{"entityId":"project","field":"id","cardinality":"1"},"target":{"entityId":"review","field":"projectId","cardinality":"N"}},{"id":"plan-tasks","label":"tasks","source":{"entityId":"plan","field":"id","cardinality":"1"},"target":{"entityId":"task","field":"planId","cardinality":"N"}},{"id":"plan-assets","label":"assets","source":{"entityId":"plan","field":"id","cardinality":"1"},"target":{"entityId":"asset","field":"planId","cardinality":"N"}},{"id":"plan-wireframes","label":"wireframes","source":{"entityId":"plan","field":"id","cardinality":"1"},"target":{"entityId":"wireframe","field":"planId","cardinality":"N"}},{"id":"plan-designs","label":"designs","source":{"entityId":"plan","field":"id","cardinality":"1"},"target":{"entityId":"design","field":"planId","cardinality":"N"}},{"id":"plan-reviews","label":"reviews","source":{"entityId":"plan","field":"id","cardinality":"1"},"target":{"entityId":"review","field":"planId","cardinality":"N"}},{"id":"task-assets","label":"assets","source":{"entityId":"task","field":"id","cardinality":"1"},"target":{"entityId":"asset","field":"taskId","cardinality":"N"}},{"id":"task-wireframes","label":"wireframes","source":{"entityId":"task","field":"id","cardinality":"1"},"target":{"entityId":"wireframe","field":"taskId","cardinality":"N"}},{"id":"task-designs","label":"designs","source":{"entityId":"task","field":"id","cardinality":"1"},"target":{"entityId":"design","field":"taskId","cardinality":"N"}},{"id":"asset-designs","label":"designs","source":{"entityId":"asset","field":"id","cardinality":"1"},"target":{"entityId":"design","field":"assetId","cardinality":"N"}},{"id":"wireframe-designs","label":"designs","source":{"entityId":"wireframe","field":"id","cardinality":"1"},"target":{"entityId":"design","field":"wireframeId","cardinality":"N"}}]}'
WHERE "projectId" IN (
  SELECT "id"
  FROM "Project"
  WHERE "repoPath" = '/mock/yusung-harness/dashboard-preview'
)
AND (
  (
    "title" = 'System Context & Boundaries'
    AND "content" = 'Harness Agent → MCP Streamable HTTP → NestJS Domain Services → Prisma Adapter → SQLite\n\nNext.js는 서버 전용 API 클라이언트로 프로젝트 컨텍스트를 조회하고 Client Component에는 탐색에 필요한 DTO만 전달합니다.'
  )
  OR (
    "title" = 'MCP Tool Routing'
    AND "content" = 'mcp.service.ts는 프로토콜과 도구 등록을 담당합니다. 각 도구의 비즈니스 로직은 plans, tasks, architectures, designs 등 소유 도메인 서비스로 위임합니다.'
  )
  OR (
    "title" = 'Frontend Data Flow'
    AND "content" = 'App Router Server Component가 프로젝트 목록과 컨텍스트를 병렬 조회합니다. URL의 type과 id가 목록 필터 및 선택 상태의 단일 진실 공급원입니다.'
  )
);

UPDATE "Architecture"
SET "content" = '{"kind":"domain-erd","schemaVersion":1,"name":"Remote Commerce Domain Model","sourceRevision":"demo-architecture-v1","entities":[{"id":"catalog","name":"Catalog","domain":"commerce","fields":[{"name":"id","type":"String","nullable":false,"primaryKey":true}]},{"id":"product","name":"Product","domain":"commerce","fields":[{"name":"id","type":"String","nullable":false,"primaryKey":true},{"name":"catalogId","type":"String","nullable":false,"foreignKey":true}]},{"id":"order","name":"Order","domain":"ordering","fields":[{"name":"id","type":"String","nullable":false,"primaryKey":true}]},{"id":"orderItem","name":"OrderItem","domain":"ordering","fields":[{"name":"id","type":"String","nullable":false,"primaryKey":true},{"name":"orderId","type":"String","nullable":false,"foreignKey":true},{"name":"productId","type":"String","nullable":false,"foreignKey":true}]}],"relationships":[{"id":"catalog-products","label":"products","source":{"entityId":"catalog","field":"id","cardinality":"1"},"target":{"entityId":"product","field":"catalogId","cardinality":"N"}},{"id":"order-items","label":"items","source":{"entityId":"order","field":"id","cardinality":"1"},"target":{"entityId":"orderItem","field":"orderId","cardinality":"N"}},{"id":"product-order-items","label":"order items","source":{"entityId":"product","field":"id","cardinality":"1"},"target":{"entityId":"orderItem","field":"productId","cardinality":"N"}}]}'
